-- Daily Task: ekspor database (PostgreSQL / MySQL / SQLite)
-- Dibuat 2026-10-10T11:51:21+07:00
-- Waktu *_at dalam milidetik Unix. Kolom JSON disimpan sebagai teks.

CREATE TABLE team (
  id VARCHAR(64) PRIMARY KEY, name VARCHAR(120), role VARCHAR(120), unit VARCHAR(20),
  is_admin BOOLEAN, admin_units TEXT, sort_order INT, email VARCHAR(200), claude_uid VARCHAR(40), photo TEXT
);
CREATE TABLE tasks (
  id VARCHAR(64) PRIMARY KEY, member_id VARCHAR(64) REFERENCES team(id), task_date VARCHAR(10), title TEXT, note TEXT,
  start_time VARCHAR(5), due_time VARCHAR(5), status VARCHAR(10), hot BOOLEAN, need_proof BOOLEAN,
  created_by VARCHAR(10), from_admin VARCHAR(120), source VARCHAR(200), routine_id VARCHAR(40),
  created_at BIGINT, started_at BIGINT, done_at BIGINT, returned_at BIGINT,
  proof_link TEXT, proof_photo_file VARCHAR(200), proof_at BIGINT, report TEXT, report_at BIGINT,
  edited_by VARCHAR(120), edited_at BIGINT, comments TEXT
);
CREATE TABLE routines (
  id VARCHAR(40), member_id VARCHAR(64) REFERENCES team(id), title TEXT, note TEXT, start_time VARCHAR(5), due_time VARCHAR(5),
  days VARCHAR(20), hot BOOLEAN, need_proof BOOLEAN, by_name VARCHAR(120), PRIMARY KEY (id, member_id)
);
CREATE TABLE admin_links (id VARCHAR(40) PRIMARY KEY, title TEXT, url TEXT, created_at BIGINT);


